<?php
session_start();if(empty($_SESSION['user_id'])){header('Location: login.html');exit;}
require __DIR__.'/db.php';require __DIR__.'/event-common.php';
$uid=(int)$_SESSION['user_id'];if(!eventArtist($conn,$uid)){http_response_code(403);exit('Artist account required to submit artworks to exhibitions.');}
$eventId=filter_input(INPUT_GET,'event_id',FILTER_VALIDATE_INT);
if(!$eventId){http_response_code(404);exit('Exhibition not found');}
$s=$conn->prepare("SELECT event_id,title,starts_at,registration_deadline,poster_path FROM events WHERE event_id=? AND status='published'");$s->bind_param('i',$eventId);$s->execute();$event=$s->get_result()->fetch_assoc();$s->close();if(!$event){http_response_code(404);exit('Exhibition not found');}
$s=$conn->prepare("SELECT a.artwork_id,a.title,(SELECT image_path FROM artwork_images ai WHERE ai.artwork_id=a.artwork_id ORDER BY image_id LIMIT 1) AS image_path,er.status AS request_status,er.admin_note FROM artworks a LEFT JOIN exhibition_requests er ON er.artwork_id=a.artwork_id AND er.event_id=? WHERE a.user_id=? AND LOWER(a.status)='approved' ORDER BY a.created_at DESC");$s->bind_param('ii',$eventId,$uid);$s->execute();$art=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();
$open=strtotime($event['registration_deadline'])>=time() && strtotime($event['starts_at'])>time();
$msg=['sent'=>'Request submitted for admin review.','error'=>'Unable to submit request.','closed'=>'Artwork requests are closed.','invalid'=>'Invalid artwork selected.'][($_GET['msg']??'')]??'';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Exhibit My Artwork | MIRA</title><link rel="stylesheet" href="event.css"><script src="theme.js" defer></script><link rel="stylesheet" href="mira-student-nav.css?v=2"></head><body class="event-page"><?php require __DIR__ . "/mira-student-nav.php"; ?><main class="event-container"><p class="event-eyebrow">MIRA STUDENT STUDIO</p><h1>Request to exhibit artwork ✦</h1><h2><?=eventEsc($event['title'])?></h2><p class="event-muted">Choose one of your approved artworks. The admin will review your request. This is separate from registering to attend an exhibition.</p><?php if($msg):?><p class="event-alert"><?=eventEsc($msg)?></p><?php endif;?><section class="event-request-grid">
<?php foreach($art as $a):?><article class="event-request-card"><?php if(preg_match('~^uploads/artworks/[a-zA-Z0-9_-]+\.(jpg|jpeg|png|webp)$~i',(string)$a['image_path'])):?><img src="<?=eventEsc($a['image_path'])?>" alt="<?=eventEsc($a['title'])?>"><?php endif;?><h3><?=eventEsc($a['title'])?></h3><?php if($a['request_status']):?><p class="event-request-status">Request: <?=eventEsc(ucfirst($a['request_status']))?></p><?php if($a['admin_note']):?><p><?=eventEsc($a['admin_note'])?></p><?php endif;?><?php elseif($open):?><form method="post" action="submit-exhibition-request.php"><input type="hidden" name="csrf" value="<?=eventEsc(eventToken())?>"><input type="hidden" name="event_id" value="<?=(int)$eventId?>"><input type="hidden" name="artwork_id" value="<?=(int)$a['artwork_id']?>"><button class="event-primary" type="submit">Request to exhibit this artwork</button></form><?php else:?><p class="event-muted">Requests closed</p><?php endif;?></article><?php endforeach;?>
<?php if(!$art):?><div class="event-card"><p>You have no approved artwork yet. Upload artwork and wait for approval before requesting an exhibition.</p><a href="upload-artwork.php">Upload artwork</a></div><?php endif;?></section></main></body></html>
